mapper.select:
/* selectMasterMpSoPayRegMngList */ SELECT PRM.PAY_REG_NO ,PRM.PAY_REG_SEQ ,PRM.GW_PAY_REG_NO ,DECODE(PRM.PAY_REG_STATUS,'S', '신규등록', DECODE(PRM.PAY_REG_STATUS, 'T', '품의중', DECODE(PRM.PAY_REG_STATUS, 'B', '품의반려', '확정'))) AS PAY_REG_STATUS -- S:신규등록,T:품의중,B:품의반려, C:확정 ,PRM.PO_NO ,PRM.PO_SEQ ,PRM.BUYER ,PRM.BUYER_ITEM_NO ,'0' AS BUYER_ITEM_NO_IMG ,PRM.PR_NO ,PRM.PR_SEQ ,PRM.GR_NO ,PRM.GR_SEQ ,PRM.AGENT ,PRM.BUYER_NAME ,PRM.BUYER_IRS_NO ,PRM.AGENT_NAME ,PRM.AGENT_IRS_NO ,TO_CHAR(TO_DATE(PRM.SCHD_CLOSE_MONTH, 'YYYYMM'), 'YYYY/MM') AS SCHD_CLOSE_MONTH ,TO_CHAR(TO_DATE(PRM.SCHD_CLOSE_MONTH, 'YYYYMM'), 'YYYY/MM') AS DB_SCHD_CLOSE_MONTH ,'1' AS SCHD_CLOSE_MONTH_IMG ,PRM.PAY_REG_TYPE ,DECODE(PRM.PAY_REG_TYPE, 'A', PRM.PAY_AMT, '') AS PAY_AMT1 ,DECODE(PRM.PAY_REG_TYPE, 'B', PRM.PAY_AMT, '') AS PAY_AMT2 ,DECODE(PRM.PAY_REG_TYPE, 'C', PRM.PAY_AMT, '') AS PAY_AMT3 ,DECODE(PRM.PAY_REG_TYPE, 'D', PRM.PAY_AMT, '') AS PAY_AMT4 ,PRM.REMARK ,TO_CHAR(PRM.ADD_DATE, 'YYYY/MM/DD') AS ADD_DATE ,PRM.ADD_USER_ID ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PRM.ADD_USER_ID) AS ADD_USER_NAME ,TO_CHAR(TO_DATE(PRM.BILL_CLOSE_MONTH, 'YYYYMM'), 'YYYY/MM') AS BILL_CLOSE_MONTH ,TAX_AMT FROM PAY_REG_MNG PRM WHERE 1=1 AND PRM.STATUS IN ('C','R')
AND PRM.SCHD_CLOSE_MONTH = #{st_from_date}
AND PRM.BUYER = #{st_buyer_code}
AND PRM.BUYER_IRS_NO LIKE '%'|| #{st_buyer_irs_no} ||'%'
AND PRM.PAY_REG_STATUS = #{st_pay_reg_status}
AND (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PRM.ADD_USER_ID) LIKE '%'|| #{st_add_user_name} ||'%'
AND PRM.AGENT = #{st_agent_code}
AND REPLACE(PRM.AGENT_IRS_NO,'-','') LIKE '%'|| REPLACE(#{st_agent_irs_no},'-','') ||'%'
AND UPPER(PRM.PO_NO) LIKE UPPER('%'||#{st_po_no}||'%')
AND PRM.BUYER_ITEM_NO LIKE '%'|| #{st_buyer_item_no} ||'%'

mapper.update:

/* updateMasterMpSoPayRegMngList */
UPDATE PAY_REG_MNG
SET  BUYER = #{BUYER}
	,STATUS = 'R'
	,PO_NO = #{PO_NO}
	,PO_SEQ = #{PO_SEQ}
	,BUYER_ITEM_NO = #{BUYER_ITEM_NO}
	,PR_NO = #{PR_NO}
	,PR_SEQ = #{PR_SEQ}
	,GR_NO = #{GR_NO}
	,GR_SEQ = #{GR_SEQ}
	,AGENT = #{AGENT}
	,AGENT_NAME = #{AGENT_NAME}
	,AGENT_IRS_NO = #{AGENT_IRS_NO}
	,BUYER_NAME = #{BUYER_NAME}
	,BUYER_IRS_NO = #{BUYER_IRS_NO}
	,SCHD_CLOSE_MONTH = #{SCHD_CLOSE_MONTH}
	,PAY_REG_TYPE = #{PAY_REG_TYPE}
	,PAY_AMT = #{PAY_AMT}
	,TAX_AMT = #{TAX_AMT}
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}
	,CHANGE_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
WHERE 1=1
AND PAY_REG_NO = #{PAY_REG_NO}
AND PAY_REG_SEQ = #{PAY_REG_SEQ}


/* deleteMasterMpSoPayRegMngList */
UPDATE PAY_REG_MNG
SET  
	 STATUS = 'D'				
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}
	,CHANGE_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
WHERE 1=1
AND PAY_REG_NO = #{PAY_REG_NO}
AND PAY_REG_SEQ = #{PAY_REG_SEQ}


